var values = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

function romanToInt(s) {
  var total = 0;
  for (var i = 0; i < s.length; i++) {
    var current = values[s.charAt(i)];
    var next = values[s.charAt(i + 1)];
    if (next > current) {
      total -= current;
    } else {
      total += current;
    }
  }
  return total;
}

console.log(romanToInt("III"), romanToInt("IV"), romanToInt("MCMXCIV"));
